// ── Animations ────────────────────────────────────────────────────────────
//
// Three closed kinds emitted as three typed structs. Runtime helpers in
// animation_helpers.go consume these (DecayStep, SinPulse, FadeFactor).
// Editing DESIGN.md's animations: block and re-running the generator is
// the only way to change cadence — never inline magic numbers in draw
// call sites.

// ExpDecayAnim drives a per-frame exponential decay loop: v *= rate
// each tick; exit when v < threshold.
type ExpDecayAnim struct {
	Rate      float64
	Threshold float64
}

// SinPulseAnim drives a per-frame oscillator: out = base + amplitude *
// |sin(frame * frame-step)|. AlphaScale (uint8) is the optional
// 0..255 ceiling when the output drives an alpha channel.
type SinPulseAnim struct {
	FrameStep  float64
	Amplitude  float64
	Base       float64
	AlphaScale uint8
}

// FadeFactor is a 0..1 multiplier applied via fadeColor() at the call
// site. One typed alias per role keeps the call site readable.
type FadeFactor float64

var (
	genAnimHighlightDecay                = ExpDecayAnim{Rate: 0.8, Threshold: 0.02}                                  // animations.highlight-decay
	genAnimButtonPressDecay              = ExpDecayAnim{Rate: 0.6, Threshold: 0.01}                                  // animations.button-press-decay
	genAnimButtonHoverFade               = ExpDecayAnim{Rate: 0.65, Threshold: 0.01}                                 // animations.button-hover-fade
	genAnimButtonEngageFlash             = ExpDecayAnim{Rate: 0.82, Threshold: 0.02}                                 // animations.button-engage-flash
	genAnimPlayheadPulse                 = SinPulseAnim{FrameStep: 0.05, Amplitude: 0.6, Base: 0.4, AlphaScale: 120} // animations.playhead-pulse
	genAnimButtonTogglePulse             = SinPulseAnim{FrameStep: 0.08, Amplitude: 0.5, Base: 0.5, AlphaScale: 110} // animations.button-toggle-pulse
	genAnimSignalGlowOuter    FadeFactor = 0.3                                                                       // animations.signal-glow-outer
	genAnimNodeTriggerGlow    FadeFactor = 0.35                                                                      // animations.node-trigger-glow
	genAnimPlayheadColumnFade FadeFactor = 0.85                                                                      // animations.playhead-column-fade
	genAnimEdgeFaded          FadeFactor = 0.6                                                                       // animations.edge-faded
	genAnimHighlightFaded     FadeFactor = 0.5                                                                       // animations.highlight-faded
	genAnimButtonGlowRest     FadeFactor = 0.25                                                                      // animations.button-glow-rest
)

